/** Stable game host that lets a player select a manifest-backed game. */
import { GamePicker } from "./game-picker";

/**
 * What it does: Mounts the stable game selector at /manual-copy/play.
 * Can be generated by AI?: No.
 */
export default async function PlayPage({ searchParams }: PageProps<"/manual-copy/play">) {
  const requestedGame = (await searchParams).game;
  const initialGame = requestedGame === "memory" || requestedGame === "sudoku" || requestedGame === "fish" ? requestedGame : "fish";
  return <GamePicker initialGame={initialGame} />;
}
